{
    // -------------------------------------------------------------------
    //  Constructors
    // -------------------------------------------------------------------
    public CMException(int errCode)
    {
        fErrorCode = errCode;
    }

    // -------------------------------------------------------------------
    //  Package methods
    // -------------------------------------------------------------------
    public int getErrorCode()
    {
        return fErrorCode;
    }


    // -------------------------------------------------------------------
    //  Private constants
    // -------------------------------------------------------------------
    static final int       fUnused = -1000;


    // -------------------------------------------------------------------
    //  Private data members
    //
    //  fErrorCode
    //      The id from ErrorCode for the error being reported.
    // -------------------------------------------------------------------
    private int     fErrorCode;
};

